def allParses(self,meter=None,include_bounded=False,one_per_meter=True):
		"""Return a list of lists of parses."""
        parses = []
        for parse in self.parses:
            if meter is None or parse.meter == meter:
                parses.append(parse)
        if not include_bounded:
            parses = [parse for parse in parses if not parse.is_bounded]
        if one_per_meter:
            parses = list(set(parses))
        return parses

