def softmax_cross_entropy_with_logits(logits, targets, vocab_dim, z_loss=0.0):
    if logits.shape!= targets.shape:
        raise ValueError("Logits and targets must have the same shape.")
    if vocab_dim not in logits.shape:
        raise ValueError("Logits must have vocab_dim in its shape.")
    if z_loss < 0.0:
        raise ValueError("z_loss must be non-negative.")
    log_probs = mtf.softmax(logits, vocab_dim)
    cross_entropy = -mtf.reduce_sum(targets * log_probs, vocab_dim)
    if z_loss > 0.0:
        z = mtf.reduce_sum(mtf.exp(logits), vocab_dim)
        cross_entropy += z_loss * mtf.reduce_sum(mtf.log(z) ** 2)

    return cross_entropy

