def do_logout_service(request, data, binding, config_loader_path=None, next_page=None,
                   logout_error_template='djangosaml2/logout_error.html'):
    """SAML Logout Response endpoint

    The IdP will send the logout response to this view,
    which will process it with pysaml2 help and log the user
    out.
    Note that the IdP can request a logout even when
    we didn't initiate the process as a single logout
    request started by another SP.
    """
    from saml2 import BINDING_HTTP_POST, BINDING_HTTP_REDIRECT
    from saml2.client import Saml2Client
    from django.conf import settings
    from django.contrib.auth import logout
    from django.http import HttpResponseRedirect
    from django.shortcuts import render
    from djangosaml2.cache import Cache
    from djangosaml2.utils import get_custom_setting, get_location

    if not data:
        return render(request, logout_error_template, {})
    client = Saml2Client(
        entity_id=get_custom_setting('SAML_ENTITY_ID'),
        identity_cache=Cache(request.session),
    )
    logout_info = client.parse_logout_request(data, binding)
    if binding == BINDING_HTTP_POST:
        response_binding = BINDING_HTTP_POST
    elif binding == BINDING_HTTP_REDIRECT:
        response_binding = BINDING_HTTP_REDIRECT
    else:
        return render(request, logout_error_template, {})
    if logout_info['type'] == 'logout_request':
        if get_custom_setting('SAML_LOGOUT_REQUEST_PREFERRED_BINDING') == BINDING_HTTP_POST:
            response_binding = BINDING_HTTP_POST
        elif get_custom_setting('SAML_LOGOUT_REQUEST_PREFERRED_BINDING') == BINDING_HTTP_REDIRECT:
            response_binding = BINDING_HTTP_REDIRECT
        else:
            return render(request, logout_error_template, {})
    if response_binding == BINDING_HTTP_POST:
        response = client.create_logout_response(logout_info, binding=BINDING_HTTP_POST,

